package session

import (
	"errors"
	"fmt"
	"log"
	"sync"
	"time"

	"github.com/m1guelpf/chatgpt-telegram/src/ref"
	"github.com/playwright-community/playwright-go"
)

func GetSession() (string, error) {
	runOptions := playwright.RunOptions{
		Browsers: []string{"chromium"},
		Verbose:  false,
	}
	err := playwright.Install(&runOptions)
	if err != nil {
		return "", errors.New(fmt.Sprintf("Couldn't install headless browser: %v", err))
	}

	pw, err := playwright.Run(&runOptions)
	if err != nil {
		return "", errors.New(fmt.Sprintf("Couldn't start headless browser: %v", err))
	}

	browser, page, err := launchBrowser(pw, "https://chat.openai.com", true)
	if err != nil {
		return "", errors.New(fmt.Sprintf("Couldn't launch headless browser: %v", err))
	}

	for page.URL() != "https://chat.openai.com/chat" {
		result := <-logIn(pw)
		if result.Error != nil {
			return "", errors.New(fmt.Sprintf("Couldn't log in: %v", result.Error))
		}

		authCookie := playwright.BrowserContextAddCookiesOptionsCookies{
			Path:     ref.Of("/"),
			Secure:   ref.Of(true),
			HttpOnly: ref.Of(true),
			Value:    ref.Of(result.SessionToken),
			Domain:   ref.Of("chat.openai.com"),
			SameSite: playwright.SameSiteAttributeLax,
			Name:     ref.Of("__Secure-next-auth.session-token"),
			Expires:  ref.Of(float64(time.Now().AddDate(0, 1, 0).Unix())),
		}

		if err := browser.AddCookies(authCookie); err != nil {
			return "", errors.New(fmt.Sprintf("Couldn't save session to browser: %v", err))
		}

		if _, err = page.Goto("https://chat.openai.com/chat"); err != nil {
			return "", errors.New(fmt.Sprintf("Couldn't reload page: %v", err))
		}
	}

	sessionToken, err := getSessionCookie(browser)
	if err != nil {
		return "", errors.New(fmt.Sprintf("Couldn't get session token: %v", err))
	}

	if err := browser.Close(); err != nil {
		return "", errors.New(fmt.Sprintf("Couldn't close headless browser: %v", err))
	}
	if err := pw.Stop(); err != nil {
		return "", errors.New(fmt.Sprintf("Couldn't stop headless browser: %v", err))
	}

	return sessionToken, nil
}

func launchBrowser(pw *playwright.Playwright, url string, headless bool) (playwright.BrowserContext, playwright.Page, error) {
	browser, err := pw.Chromium.LaunchPersistentContext("/tmp/chatgpt", playwright.BrowserTypeLaunchPersistentContextOptions{Headless: playwright.Bool(headless)})
	if err != nil {
		return nil, nil, errors.New(fmt.Sprintf("Couldn't launch headless browser: %v", err))
	}
	page, err := browser.NewPage()
	if err != nil {
		return nil, nil, errors.New(fmt.Sprintf("Couldn't create a new tab on headless browser: %v", err))
	}

	if _, err = page.Goto(url); err != nil {
		return nil, nil, errors.New(fmt.Sprintf("Couldn't open website: %v", err))
	}

	return browser, page, nil
}

type Result struct {
	Error        error
	SessionToken string
}

func logIn(pw *playwright.Playwright) <-chan Result {
	var lock sync.Mutex
	r := make(chan Result)

	lock.Lock()
	go func() {
		defer close(r)
		defer lock.Unlock()

		browser, page, err := launchBrowser(pw, "https://chat.openai.com/", false)
		if err != nil {
			r <- Result{Error: errors.New(fmt.Sprintf("Couldn't launch headless browser: %v", err))}
			return
		}
		log.Println("Please log in to OpenAI Chat")

		page.On("framenavigated", func(frame playwright.Frame) {
			if frame.URL() != "https://chat.openai.com/chat" {
				return
			}

			lock.Unlock()
		})

		lock.Lock()

		sessionToken, err := getSessionCookie(browser)
		if err != nil {
			r <- Result{Error: errors.New(fmt.Sprintf("Couldn't get session token: %v", err))}
			return
		}

		if err := browser.Close(); err != nil {
			r <- Result{Error: errors.New(fmt.Sprintf("Couldn't close headless browser: %v", err))}
			return
		}

		r <- Result{SessionToken: sessionToken}
	}()

	return r
}

func getSessionCookie(browser playwright.BrowserContext) (string, error) {
	cookies, err := browser.Cookies("https://chat.openai.com/")
	if err != nil {
		return "", errors.New(fmt.Sprintf("Couldn't get cookies: %v", err))
	}

	var sessionToken string
	for _, cookie := range cookies {
		if cookie.Name == "__Secure-next-auth.session-token" {
			sessionToken = cookie.Value
			break
		}
	}

	if sessionToken == "" {
		return "", errors.New(fmt.Sprintf("Couldn't get session token"))
	}

	return sessionToken, nil
}

package sse

import (
	"encoding/json"
	"errors"
	"fmt"
	"log"
	"net/http"
	"strings"

	"github.com/google/uuid"
	"github.com/launchdarkly/eventsource"
)

type Client struct {
	URL          string
	EventChannel chan string
	Headers      map[string]string
}

func Init(url string) Client {
	return Client{
		URL:          url,
		EventChannel: make(chan string),
	}
}

func (c *Client) Connect(message string, conversationId string, parentMessageId string) error {
	messages, err := json.Marshal([]string{message})
	if err != nil {
		return errors.New(fmt.Sprintf("failed to encode message: %v", err))
	}

	if parentMessageId == "" {
		parentMessageId = uuid.NewString()
	}

	var conversationIdString string
	if conversationId != "" {
		conversationIdString = fmt.Sprintf(`, "conversation_id": "%s"`, conversationId)
	}

	// if conversation id is empty, don't send it
	body := fmt.Sprintf(`{
        "action": "next",
        "messages": [
            {
                "id": "%s",
                "role": "user",
                "content": {
                    "content_type": "text",
                    "parts": %s
                }
            }
        ],
        "model": "text-davinci-002-render",
		"parent_message_id": "%s"%s
    }`, uuid.NewString(), string(messages), parentMessageId, conversationIdString)

	req, err := http.NewRequest("POST", c.URL, strings.NewReader(body))
	if err != nil {
		return errors.New(fmt.Sprintf("failed to create request: %v", err))
	}

	for key, value := range c.Headers {
		req.Header.Set(key, value)
	}
	req.Header.Set("Accept", "text/event-stream")
	req.Header.Set("Content-Type", "application/json")

	http := &http.Client{}
	resp, err := http.Do(req)
	if err != nil {
		return errors.New(fmt.Sprintf("failed to connect to SSE: %v", err))
	}

	if resp.StatusCode != 200 {
		return errors.New(fmt.Sprintf("failed to connect to SSE: %v", resp.Status))
	}

	decoder := eventsource.NewDecoder(resp.Body)

	go func() {
		defer resp.Body.Close()
		defer close(c.EventChannel)

		for {
			event, err := decoder.Decode()
			if err != nil {
				log.Println(errors.New(fmt.Sprintf("failed to decode event: %v", err)))
				break
			}
			if event.Data() == "[DONE]" || event.Data() == "" {
				break
			}

			c.EventChannel <- event.Data()
		}
	}()

	return nil
}

package tgbot

import (
	"log"
	"os"
	"time"

	tgbotapi "github.com/go-telegram-bot-api/telegram-bot-api/v5"
	"github.com/m1guelpf/chatgpt-telegram/src/chatgpt"
	"github.com/m1guelpf/chatgpt-telegram/src/markdown"
	"github.com/m1guelpf/chatgpt-telegram/src/ratelimit"
)

type Bot struct {
	Username     string
	api          *tgbotapi.BotAPI
	editInterval time.Duration
}

func New(token string, editInterval time.Duration) (*Bot, error) {
	var api *tgbotapi.BotAPI
	var err error
	apiEndpoint, exist := os.LookupEnv("TELEGRAM_API_ENDPOINT")
	if exist && apiEndpoint != "" {
		api, err = tgbotapi.NewBotAPIWithAPIEndpoint(token, apiEndpoint)
	} else {
		api, err = tgbotapi.NewBotAPI(token)
	}
	if err != nil {
		return nil, err
	}

	return &Bot{
		Username:     api.Self.UserName,
		api:          api,
		editInterval: editInterval,
	}, nil
}

func (b *Bot) GetUpdatesChan() tgbotapi.UpdatesChannel {
	cfg := tgbotapi.NewUpdate(0)
	cfg.Timeout = 30
	return b.api.GetUpdatesChan(cfg)
}

func (b *Bot) Stop() {
	b.api.StopReceivingUpdates()
}

func (b *Bot) Send(chatID int64, replyTo int, text string) (tgbotapi.Message, error) {
	text = markdown.EnsureFormatting(text)
	msg := tgbotapi.NewMessage(chatID, text)
	msg.ReplyToMessageID = replyTo
	return b.api.Send(msg)
}

func (b *Bot) SendEdit(chatID int64, messageID int, text string) error {
	text = markdown.EnsureFormatting(text)
	msg := tgbotapi.NewEditMessageText(chatID, messageID, text)
	msg.ParseMode = "Markdown"
	if _, err := b.api.Send(msg); err != nil {
		if err.Error() == "Bad Request: message is not modified: specified new message content and reply markup are exactly the same as a current content and reply markup of the message" {
			return nil
		}
		return err
	}
	return nil
}

func (b *Bot) SendTyping(chatID int64) {
	if _, err := b.api.Request(tgbotapi.NewChatAction(chatID, "typing")); err != nil {
		log.Printf("Couldn't send typing action: %v", err)
	}
}

func (b *Bot) SendAsLiveOutput(chatID int64, replyTo int, feed chan chatgpt.ChatResponse) {
	debouncedType := ratelimit.Debounce(10*time.Second, func() { b.SendTyping(chatID) })
	debouncedEdit := ratelimit.DebounceWithArgs(b.editInterval, func(text interface{}, messageId interface{}) {
		if err := b.SendEdit(chatID, messageId.(int), text.(string)); err != nil {
			log.Printf("Couldn't edit message: %v", err)
		}
	})

	var message tgbotapi.Message
	var lastResp string

pollResponse:
	for {
		debouncedType()

		select {
		case response, ok := <-feed:
			if !ok {
				break pollResponse
			}

			lastResp = response.Message

			if message.MessageID == 0 {
				var err error
				if message, err = b.Send(chatID, replyTo, lastResp); err != nil {
					log.Fatalf("Couldn't send message: %v", err)
				}
			} else {
				debouncedEdit(lastResp, message.MessageID)
			}
		}
	}

	if err := b.SendEdit(chatID, message.MessageID, lastResp); err != nil {
		log.Printf("Couldn't perform final edit on message: %v", err)
	}
}

